templates.site-theme.html:
{% assign theme = site.data.site_design %}
<style>
    :root {
        --primary-color: {{ theme.primary_color | default: '#2563eb' }};
        --primary-hover: {{ theme.primary_hover_color | default: '#1d4ed8' }};
        --bg-color: {{ theme.background_color | default: '#f8fafc' }};
        --card-bg: {{ theme.surface_color | default: '#ffffff' }};
        --text-color: {{ theme.text_color | default: '#0f172a' }};
        --text-muted: {{ theme.muted_text_color | default: '#64748b' }};
        --brand-color: {{ theme.brand_color | default: '#006400' }};
        {% if theme.seasonal_image and theme.seasonal_image != "" %}
        --seasonal-banner-image: url("{{ theme.seasonal_image | relative_url | uri_escape | replace: '"', '%22' | replace: ')', '%29' }}");
        {% endif %}
        --button-radius: {% case theme.button_style %}{% when "square" %}0{% when "pill" %}9999px{% else %}var(--radius){% endcase %};
        --max-width: {% case theme.content_width %}{% when "narrow" %}900px{% when "wide" %}1300px{% else %}1100px{% endcase %};
        --spacing-scale: {% case theme.spacing %}{% when "compact" %}0.85{% when "spacious" %}1.15{% else %}1{% endcase %};
        --font-main: {% case theme.font_family %}{% when "lora" %}'Lora', Georgia, serif{% when "open-sans" %}'Open Sans', Arial, sans-serif{% when "georgia" %}Georgia, 'Times New Roman', serif{% else %}'Playfair Display', Georgia, 'Times New Roman', serif{% endcase %};
    }
    {% if theme.wallpaper and theme.wallpaper != "" %}
    body.has-wallpaper {
        background-image: url("{{ theme.wallpaper | relative_url | uri_escape | replace: '"', '%22' | replace: ')', '%29' }}");
    }
    {% endif %}
</style>

templates.testimonials.html:
{% assign testimonial_entries = page.testimonials %}

{% if testimonial_entries and testimonial_entries.size > 0 %}
<div class="testimonials-grid">
    {% for testimonial in testimonial_entries %}
    {% assign description = testimonial.description %}
    {% assign image_alt = testimonial.image_alt %}

    {% if testimonial.image != blank or description != blank or testimonial.name != blank %}
    <article class="testimonial-card">
        {% if testimonial.image != blank %}
        <img src="{{ testimonial.image | relative_url | escape }}" alt="{{ image_alt | default: testimonial.name | default: 'Puppy photo' | escape }}" loading="lazy">
        {% endif %}
        {% if description != blank or testimonial.name != blank %}
        <blockquote>
            {% if description != blank %}<p class="testimonial-card__description">{{ description | escape }}</p>{% endif %}
            {% if testimonial.name != blank %}<footer>{{ testimonial.name | escape }}</footer>{% endif %}
        </blockquote>
        {% endif %}
    </article>
    {% endif %}
    {% endfor %}
</div>
{% endif %}

pages.body:
{% if page.recommended_products and page.recommended_products.size > 0 %}
<div class="recommended-products-page">
  {% for product in page.recommended_products %}
  <div class="recommended-products-page__item">
    {% if product.photo and product.photo != "" %}
      <img class="recommended-products-page__image" src="{{ product.photo | relative_url }}" alt="{{ product.name | default: 'Recommended product' | escape }}">
    {% else %}
      <div class="recommended-products-page__image" role="img" aria-label="{{ product.name | default: 'Recommended product' | escape }} product placeholder"></div>
    {% endif %}

    {% if product.link and product.link != "" %}
      <a class="recommended-products-page__link" href="{{ product.link | escape }}" target="_blank" rel="noopener noreferrer">{{ product.name | default: 'Recommended product' | escape }}</a>
    {% elsif product.name and product.name != "" %}
      <p class="recommended-products-page__name">{{ product.name | escape }}</p>
    {% endif %}

    {% if product.description and product.description != "" %}
      <p class="recommended-products-page__description">{{ product.description | escape }}</p>
    {% endif %}
  </div>
  {% endfor %}
</div>
{% endif %}

